# ---------------------------------------------------------------------------
# parallel registry collector (Software hives + HKCR/COM), counters + progress
# also compiled lazily - only the deep registry phase needs it
# ---------------------------------------------------------------------------
$script:UniRegOk = $false
function Ensure-UniRegCollect {
    if ($script:UniRegOk) { return }
    if ('UniRegCollectV3' -as [type]) { $script:UniRegOk = $true; return }
    try {
        Add-Type -TypeDefinition @'
using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Text.RegularExpressions;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Win32;

public static class UniRegCollectV3
{
    private static long _scanned;
    private static long _matched;
    public static long Scanned { get { return Interlocked.Read(ref _scanned); } }
    public static long Matched { get { return Interlocked.Read(ref _matched); } }
    public static void ResetCounters() { Interlocked.Exchange(ref _scanned, 0); Interlocked.Exchange(ref _matched, 0); }

    private class Work { public int Hive; public string Rel; public string Full; public bool IsClass; public bool InDeny; }

    public static Task<List<string>> CollectAsync(string exactPattern, string loosePattern, string[] denyPrefixes)
    {
        return Task.Run(() => Collect(exactPattern, loosePattern, denyPrefixes));
    }

    public static List<string> Collect(string exactPattern, string loosePattern, string[] denyPrefixes)
    {
        var reExact = new Regex(exactPattern, RegexOptions.IgnoreCase);
        var reLoose = new Regex(loosePattern, RegexOptions.IgnoreCase);
        var reGuid = new Regex(@"^\{[0-9A-Fa-f\-]+\}$");
        var results = new ConcurrentDictionary<string, byte>(StringComparer.OrdinalIgnoreCase);
        var queue = new ConcurrentQueue<Work>();
        long pending = 0;

        EnqueueRoot(queue, ref pending, 0, "Software", "HKLM\\SOFTWARE", false, false);
        EnqueueRoot(queue, ref pending, 1, "Software", "HKLM\\SOFTWARE\\WOW6432Node", false, false);
        EnqueueRoot(queue, ref pending, 2, "Software", "HKCU\\Software", false, false);
        EnqueueRoot(queue, ref pending, 3, "", "HKCR", true, false);

        int workers = Math.Max(2, Math.Min(32, Environment.ProcessorCount * 2));
        var threads = new List<Thread>();
        for (int w = 0; w < workers; w++)
        {
            var t = new Thread(() => Worker(queue, ref pending, reExact, reLoose, reGuid, denyPrefixes, results));
            t.IsBackground = true;
            t.Start();
            threads.Add(t);
        }
        foreach (var t in threads) t.Join();

        var k = new List<string>();
        var v = new List<string>();
        foreach (var s in results.Keys)
        {
            if (s.StartsWith("K:", StringComparison.Ordinal)) k.Add(s); else v.Add(s);
        }
        k.Sort(StringComparer.OrdinalIgnoreCase);
        v.Sort(StringComparer.OrdinalIgnoreCase);
        k.AddRange(v);
        return k;
    }

    private static void EnqueueRoot(ConcurrentQueue<Work> queue, ref long pending, int hive, string rel, string full, bool isClass, bool inDeny)
    {
        Interlocked.Increment(ref pending);
        queue.Enqueue(new Work { Hive = hive, Rel = rel, Full = full, IsClass = isClass, InDeny = inDeny });
    }

    private static RegistryKey OpenWork(Work it)
    {
        try
        {
            if (it.Hive == 0) return RegistryKey.OpenBaseKey(RegistryHive.LocalMachine, RegistryView.Registry64).OpenSubKey(it.Rel);
            if (it.Hive == 1) return RegistryKey.OpenBaseKey(RegistryHive.LocalMachine, RegistryView.Registry32).OpenSubKey(it.Rel);
            if (it.Hive == 2) return RegistryKey.OpenBaseKey(RegistryHive.CurrentUser, RegistryView.Default).OpenSubKey(it.Rel);
            if (it.Rel.Length == 0) return Registry.ClassesRoot;
            return Registry.ClassesRoot.OpenSubKey(it.Rel);
        }
        catch { return null; }
    }

    private static void Worker(ConcurrentQueue<Work> queue, ref long pending, Regex reExact, Regex reLoose, Regex reGuid, string[] deny, ConcurrentDictionary<string, byte> results)
    {
        while (true)
        {
            Work it;
            if (queue.TryDequeue(out it))
            {
                try { Process(it, reExact, reLoose, reGuid, deny, results, queue, ref pending); }
                finally { Interlocked.Decrement(ref pending); }
            }
            else
            {
                if (Volatile.Read(ref pending) == 0) return;
                Thread.Sleep(2);
            }
        }
    }

    private static void Process(Work it, Regex reExact, Regex reLoose, Regex reGuid, string[] deny, ConcurrentDictionary<string, byte> results, ConcurrentQueue<Work> queue, ref long pending)
    {
        Interlocked.Increment(ref _scanned);
        using (var key = OpenWork(it))
        {
            if (key == null) return;
            string name = key.Name;
            int idx = name.LastIndexOf('\\');
            string leaf = idx >= 0 ? name.Substring(idx + 1) : name;

            if (!it.InDeny && reExact.IsMatch(leaf))
            {
                results.TryAdd("K:" + it.Full, 0);
                Interlocked.Increment(ref _matched);
                return;
            }
            if (it.IsClass && reGuid.IsMatch(leaf) && !it.InDeny)
            {
                object def = null;
                try { def = key.GetValue(null); } catch { }
                string ds = def as string;
                if (ds != null && reExact.IsMatch(ds))
                {
                    results.TryAdd("K:" + it.Full, 0);
                    Interlocked.Increment(ref _matched);
                    return;
                }
            }

            string[] vns = null;
            try { vns = key.GetValueNames(); } catch { }
            if (vns != null)
            {
                foreach (string vn in vns)
                {
                    bool match = false;
                    if (reExact.IsMatch(vn)) match = true;
                    if (!match)
                    {
                        object data = null;
                        try { data = key.GetValue(vn); } catch { }
                        string s = data as string;
                        if (s != null) match = reExact.IsMatch(s);
                        else
                        {
                            string[] ss = data as string[];
                            if (ss != null)
                            {
                                foreach (string x in ss)
                                {
                                    if (x != null && reExact.IsMatch(x)) { match = true; break; }
                                }
                            }
                        }
                    }
                    if (match)
                    {
                        results.TryAdd("V:" + it.Full + "\u0001" + vn, 0);
                        Interlocked.Increment(ref _matched);
                    }
                }
            }

            string[] sns = null;
            try { sns = key.GetSubKeyNames(); } catch { }
            if (sns != null)
            {
                foreach (string sn in sns)
                {
                    if (!it.IsClass && sn.Equals("Classes", StringComparison.OrdinalIgnoreCase)) continue;
                    string childFull = it.Full + "\\" + sn;
                    bool childDeny = it.InDeny || IsDeny(deny, childFull);
                    string childRel = it.Rel.Length == 0 ? sn : it.Rel + "\\" + sn;
                    Interlocked.Increment(ref pending);
                    queue.Enqueue(new Work { Hive = it.Hive, Rel = childRel, Full = childFull, IsClass = it.IsClass, InDeny = childDeny });
                }
            }
        }
    }

    private static bool IsDeny(string[] deny, string full)
    {
        if (deny == null) return false;
        foreach (var d in deny) if (full.StartsWith(d, StringComparison.OrdinalIgnoreCase)) return true;
        return false;
    }
}
'@ -ErrorAction Stop
        $script:UniRegOk = $true
    } catch {
        $script:UniRegOk = $false
    }
}

# ---------------------------------------------------------------------------
# delete one target with escalating force: direct -> long-path cmd -> attrib
# -> lockers (Restart Manager) -> takeown/icacls when elevated -> retries
# ---------------------------------------------------------------------------
$script:UniIsElevated = ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)

function Remove-UniTarget {
    param([string]$Path, [int]$MaxRounds = 3)
    for ($round = 0; $round -lt $MaxRounds; $round++) {
        if (-not (Test-Path -LiteralPath $Path)) { return $true }
        $isDir = $false
        try { $isDir = [System.IO.Directory]::Exists($Path) } catch { }
        $lp = $Path
        if ($lp.Length -ge 248) { $lp = '\\?\' + $lp.TrimEnd('\') }

        if ($isDir) { & cmd.exe /c rd /s /q "$lp" 2>$null }
        else { & cmd.exe /c del /f /q /a "$lp" 2>$null }
        if (-not (Test-Path -LiteralPath $Path)) { return $true }

        try { Remove-Item -LiteralPath $Path -Recurse -Force -ErrorAction Stop } catch { }
        if (-not (Test-Path -LiteralPath $Path)) { return $true }

        if ($isDir) { & attrib.exe -R -S -H "$Path" /D /S 2>$null | Out-Null }
        else { & attrib.exe -R -S -H "$Path" 2>$null | Out-Null }
        try { Remove-Item -LiteralPath $Path -Recurse -Force -ErrorAction Stop } catch { }
        if (-not (Test-Path -LiteralPath $Path)) { return $true }

        $lockers = @(Get-UniLockerPids -Path $Path)
        foreach ($pidId in $lockers) {
            if ($script:UniProtectedPids.ContainsKey($pidId)) { continue }
            try {
                $lkp = Get-Process -Id $pidId -ErrorAction Stop
                if ($script:UniNeverKill -contains $lkp.ProcessName.ToLowerInvariant()) { continue }
                Stop-Process -Id $pidId -Force -ErrorAction SilentlyContinue
            } catch { }
        }
        Start-Sleep -Milliseconds 250
        if ($isDir) { & cmd.exe /c rd /s /q "$lp" 2>$null }
        else { & cmd.exe /c del /f /q /a "$lp" 2>$null }
        try { Remove-Item -LiteralPath $Path -Recurse -Force -ErrorAction Stop } catch { }
        if (-not (Test-Path -LiteralPath $Path)) { return $true }

        if ($script:UniIsElevated) {
            if ($isDir) { & takeown.exe /F "$Path" /A /R /D Y 2>$null | Out-Null; & icacls.exe "$Path" /grant "*S-1-5-32-544:(OI)(CI)F" /T /C /Q 2>$null | Out-Null }
            else { & takeown.exe /F "$Path" /A 2>$null | Out-Null; & icacls.exe "$Path" /grant "*S-1-5-32-544:F" /C /Q 2>$null | Out-Null }
            try { Remove-Item -LiteralPath $Path -Recurse -Force -ErrorAction Stop } catch { }
            if (-not (Test-Path -LiteralPath $Path)) { return $true }
        }
        Start-Sleep -Milliseconds 200
    }
    return -not (Test-Path -LiteralPath $Path)
}

