function Get-UniTokenPattern {
    param([string]$Token)
    $sb = ''
    foreach ($c in $Token.ToCharArray()) {
        if ($sb.Length) { $sb += '[^a-z0-9]*' }
        $sb += [regex]::Escape($c.ToString())
    }
    return $sb
}

function Get-UniPatterns {
    param([string[]]$Names)
    $denyHash = New-Object System.Collections.Generic.HashSet[string]
    foreach ($d in $script:UniDenyTokens) { [void]$denyHash.Add($d) }
    $exactParts = New-Object System.Collections.Generic.List[string]
    $looseParts = New-Object System.Collections.Generic.List[string]
    $tokens = New-Object System.Collections.Generic.List[string]
    foreach ($n in $Names) {
        $t = ([string]$n -replace '[^A-Za-z0-9]', '').ToLowerInvariant()
        if ($t.Length -lt 4 -or $denyHash.Contains($t)) { continue }
        $tokens.Add($t)
        $tp = Get-UniTokenPattern -Token $t
        $exactParts.Add($tp)
        $looseParts.Add($tp)
        if ($t.Length -ge 7) {
            for ($len = 6; $len -lt $t.Length; $len++) {
                for ($i = 0; $i + $len -le $t.Length; $i++) {
                    $g = $t.Substring($i, $len)
                    if ($denyHash.Contains($g)) { continue }
                    $generic = $false
                    foreach ($d in $script:UniDenyTokens) {
                        if ($d.Length -ge 4 -and $d.Contains($g)) { $generic = $true; break }
                    }
                    if ($generic) { continue }
                    $looseParts.Add((Get-UniTokenPattern -Token $g))
                }
            }
        }
    }
    if ($tokens.Count -eq 0) { return $null }
    return @{
        Tokens = @($tokens)
        Exact  = '(?:' + ($exactParts -join '|') + ')'
        Loose  = '(?:' + ($looseParts -join '|') + ')'
    }
}

# ---------------------------------------------------------------------------
# stats
# ---------------------------------------------------------------------------
$script:UniStats = @{ Processes = 0; Services = 0; Tasks = 0; Firewall = 0; RegKeys = 0; RegValues = 0; EnvVars = 0; Shortcuts = 0; Files = 0; Dirs = 0 }
$script:UniFailed = New-Object System.Collections.Generic.List[string]
$script:UniRegSweepFound = $false

# ---------------------------------------------------------------------------
# 1. kill every related process (name / path / command line / window title)
# ---------------------------------------------------------------------------
function Invoke-UniKillProcesses {
    param($ReExact)
    $killed = @{ }
    for ($round = 1; $round -le 4; $round++) {
        $pids = @{ }
        $procs = @(Get-CimInstance Win32_Process -ErrorAction SilentlyContinue)
        foreach ($p in $procs) {
            $pidId = 0
            try { $pidId = [int]$p.ProcessId } catch { continue }
            if ($script:UniProtectedPids.ContainsKey($pidId)) { continue }
            $nm = [string]$p.Name
            if ($script:UniNeverKill -contains $nm.ToLowerInvariant()) { continue }
            $match = $false
            $nmLower = $nm.ToLowerInvariant()
            if ($ReExact.IsMatch($nm) -or $ReExact.IsMatch([string]$p.ExecutablePath)) { $match = $true }
            elseif ($ReExact.IsMatch([string]$p.CommandLine)) {
                # command-line matches are real leftovers only when the process
                # is NOT our own shell or a child of it (the shell mentions the
                # target in its command line and must never be killed)
                $isShell = $script:UniShellNames -contains $nmLower
                $ppid = 0
                try { $ppid = [int]$p.ParentProcessId } catch { }
                if (-not $isShell -and -not $script:UniProtectedPids.ContainsKey($ppid)) { $match = $true }
            }
            if ($match) { $pids[$pidId] = $nm }
        }
        foreach ($gp in @(Get-Process -ErrorAction SilentlyContinue)) {
            if ($script:UniProtectedPids.ContainsKey($gp.Id)) { continue }
            if ($script:UniNeverKill -contains $gp.ProcessName.ToLowerInvariant()) { continue }
            if ($gp.MainWindowTitle -and $ReExact.IsMatch([string]$gp.MainWindowTitle)) { $pids[$gp.Id] = $gp.ProcessName }
        }
        if ($pids.Count -eq 0) { break }
        foreach ($pidId in @($pids.Keys)) {
            if ($killed.ContainsKey($pidId)) { continue }
            $killed[$pidId] = $true
            try {
                Stop-Process -Id $pidId -Force -ErrorAction Stop
                $script:UniStats.Processes++
                Clear-UniLine
                Write-Host ("  killed: {0} (pid {1})" -f $pids[$pidId], $pidId) -ForegroundColor Green
            } catch { }
            & taskkill.exe /F /T /PID $pidId 2>$null | Out-Null
        }
        Update-UniLine ("[{0}] processes: killed {1}" -f (Get-UniElapsed), $script:UniStats.Processes)
        Start-Sleep -Milliseconds 350
    }
    Clear-UniLine
    Write-Host ("  processes: {0} killed." -f $script:UniStats.Processes) -ForegroundColor Green
}

# ---------------------------------------------------------------------------
# 2. stop + delete related services (WMI + registry Services key)
# ---------------------------------------------------------------------------
function Invoke-UniServices {
    param($ReExact)
    $svcs = @(Get-CimInstance Win32_Service -ErrorAction SilentlyContinue)
    foreach ($s in $svcs) {
        $nm = [string]$s.Name
        if ($script:UniNeverKill -contains $nm.ToLowerInvariant()) { continue }
        if (-not ($ReExact.IsMatch($nm) -or $ReExact.IsMatch([string]$s.DisplayName) -or $ReExact.IsMatch([string]$s.PathName))) { continue }
        Update-UniLine ("[{0}] services: stopping {1} ..." -f (Get-UniElapsed), $nm)
        try { Stop-Service -Name $nm -Force -ErrorAction SilentlyContinue } catch { }
        $spid = 0
        try { $spid = [int]$s.ProcessId } catch { }
        if ($spid -gt 0 -and -not $script:UniProtectedPids.ContainsKey($spid)) {
            Stop-Process -Id $spid -Force -ErrorAction SilentlyContinue
        }
        & sc.exe delete $nm 2>$null | Out-Null
        if (-not (Get-Service -Name $nm -ErrorAction SilentlyContinue)) {
            $script:UniStats.Services++
            Clear-UniLine
            Write-Host ("  service deleted: {0}" -f $nm) -ForegroundColor Green
        }
    }
    # registry services not visible via WMI (e.g. pending drivers)
    $svcKey = 'HKLM:\SYSTEM\CurrentControlSet\Services'
    if (Test-Path -LiteralPath $svcKey) {
        foreach ($k in @(Get-ChildItem -LiteralPath $svcKey -ErrorAction SilentlyContinue)) {
            $nm = $k.PSChildName
            if ($script:UniNeverKill -contains $nm.ToLowerInvariant()) { continue }
            if (-not $ReExact.IsMatch($nm)) { continue }
            Update-UniLine ("[{0}] services: deleting {1} ..." -f (Get-UniElapsed), $nm)
            & sc.exe delete $nm 2>$null | Out-Null
            Remove-Item -LiteralPath $k.PSPath -Recurse -Force -ErrorAction SilentlyContinue
            $script:UniStats.Services++
            Clear-UniLine
            Write-Host ("  service deleted (registry): {0}" -f $nm) -ForegroundColor Green
        }
    }
    Clear-UniLine
    Write-Host ("  services: {0} deleted." -f $script:UniStats.Services) -ForegroundColor Green
}

# ---------------------------------------------------------------------------
# 3. delete related scheduled tasks (incl. .job leftovers via filesystem pass)
# ---------------------------------------------------------------------------
function Invoke-UniTasks {
    param($ReExact)
    $found = 0
    if (Get-Command Get-ScheduledTask -ErrorAction SilentlyContinue) {
        $tasks = @(Get-ScheduledTask -ErrorAction SilentlyContinue)
        foreach ($t in $tasks) {
            $tn = [string]$t.TaskName
            $exec = ''
            $args = ''
            try { if ($t.Actions -and $t.Actions.Count) { $exec = [string]$t.Actions[0].Execute; $args = [string]$t.Actions[0].Arguments } } catch { }
            if (-not ($ReExact.IsMatch($tn) -or $ReExact.IsMatch($exec) -or $ReExact.IsMatch($args))) { continue }
            Update-UniLine ("[{0}] tasks: deleting {1} ..." -f (Get-UniElapsed), $tn)
            try {
                Unregister-ScheduledTask -TaskName $tn -TaskPath ([string]$t.TaskPath) -Confirm:$false -ErrorAction Stop
                $found++
            } catch {
                & schtasks.exe /Delete /TN "$tn" /F 2>$null | Out-Null
                if (-not (Get-ScheduledTask -TaskName $tn -TaskPath ([string]$t.TaskPath) -ErrorAction SilentlyContinue)) { $found++ }
            }
            if ($found -gt $script:UniStats.Tasks) {
                $script:UniStats.Tasks = $found
                Clear-UniLine
                Write-Host ("  task deleted: {0}" -f $tn) -ForegroundColor Green
            }
        }
    } else {
        $out = @(schtasks.exe /Query /FO CSV /V 2>$null | Select-Object -Skip 1)
        if ($out.Count -gt 0) {
            $rows = @($out | ConvertFrom-Csv -ErrorAction SilentlyContinue)
            foreach ($r in $rows) {
                $tn = [string]$r.TaskName
                $run = [string]$r.'Task To Run'
                if (-not ($ReExact.IsMatch($tn) -or $ReExact.IsMatch($run))) { continue }
                & schtasks.exe /Delete /TN "$tn" /F 2>$null | Out-Null
                $script:UniStats.Tasks++
                Clear-UniLine
                Write-Host ("  task deleted: {0}" -f $tn) -ForegroundColor Green
            }
        }
    }
    Clear-UniLine
    Write-Host ("  scheduled tasks: {0} deleted." -f $script:UniStats.Tasks) -ForegroundColor Green
}

# ---------------------------------------------------------------------------
# 4. delete related firewall rules
# ---------------------------------------------------------------------------
function Invoke-UniFirewall {
    param($ReExact)
    $found = 0
    if (Get-Command Get-NetFirewallRule -ErrorAction SilentlyContinue) {
        $rules = @(Get-NetFirewallRule -ErrorAction SilentlyContinue)
        foreach ($r in $rules) {
            if (-not ($ReExact.IsMatch([string]$r.DisplayName) -or $ReExact.IsMatch([string]$r.Name))) { continue }
            Update-UniLine ("[{0}] firewall: removing {1} ..." -f (Get-UniElapsed), $r.DisplayName)
            try {
                Remove-NetFirewallRule -Name $r.Name -ErrorAction Stop
                $found++
                $script:UniStats.Firewall = $found
                Clear-UniLine
                Write-Host ("  firewall rule removed: {0}" -f $r.DisplayName) -ForegroundColor Green
            } catch { }
        }
    } else {
        $out = @(netsh advfirewall firewall show rule name=all 2>$null)
        for ($i = 0; $i -lt $out.Count; $i++) {
            if ($out[$i] -match '^Rule Name:\s*(.+)$') {
                $rn = $matches[1].Trim()
                if ($ReExact.IsMatch($rn)) {
                    netsh advfirewall firewall delete rule name="$rn" 2>$null | Out-Null
                    $found++
                    $script:UniStats.Firewall = $found
                    Clear-UniLine
                    Write-Host ("  firewall rule removed: {0}" -f $rn) -ForegroundColor Green
                }
            }
        }
    }
    Clear-UniLine
    Write-Host ("  firewall rules: {0} removed." -f $script:UniStats.Firewall) -ForegroundColor Green
}

# ---------------------------------------------------------------------------
# 5. uninstall entries / App Paths / Run & RunOnce values
# ---------------------------------------------------------------------------
function Remove-UniRegistryKey {
    param([string]$ProviderPath)
    Remove-Item -LiteralPath $ProviderPath -Recurse -Force -ErrorAction SilentlyContinue
    $cur = Split-Path -Parent $ProviderPath
    for ($i = 0; $i -lt 6 -and $cur -and $cur -match '\\Software($|\\)'; $i++) {
        if (Test-Path -LiteralPath $cur) {
            $k = Get-Item -LiteralPath $cur -ErrorAction SilentlyContinue
            if ($k -and $k.SubKeyCount -eq 0 -and @($k.GetValueNames()).Count -eq 0) {
                Remove-Item -LiteralPath $cur -Force -ErrorAction SilentlyContinue
                $cur = Split-Path -Parent $cur
            } else { break }
        } else { break }
    }
}

# remove one registry value. An empty value name means the key's DEFAULT value
# (e.g. per-app audio PolicyConfig references), which PowerShell's
# Remove-ItemProperty refuses with a parameter-binding error that
# -ErrorAction cannot silence - so empty names go through the .NET API instead.
function Remove-UniRegistryValue {
    param([string]$ProviderPath, [string]$ValueName)
    if (-not [string]::IsNullOrEmpty($ValueName)) {
        Remove-ItemProperty -LiteralPath $ProviderPath -Name $ValueName -ErrorAction SilentlyContinue
        return
    }
    try {
        $p = $ProviderPath
        if ($p.StartsWith('Registry::', [System.StringComparison]::OrdinalIgnoreCase)) { $p = $p.Substring(10) }
        $hiveName = ''
        $sub = ''
        if ($p -match '^([A-Za-z]+):\\(.*)$') { $hiveName = $matches[1]; $sub = $matches[2] }
        elseif ($p -match '^([A-Za-z]+)\\(.*)$') { $hiveName = $matches[1]; $sub = $matches[2] }
        $hive = $null
        if ($hiveName -eq 'HKCU') { $hive = [Microsoft.Win32.Registry]::CurrentUser }
        elseif ($hiveName -eq 'HKLM') { $hive = [Microsoft.Win32.Registry]::LocalMachine }
        elseif ($hiveName -eq 'HKCR') { $hive = [Microsoft.Win32.Registry]::ClassesRoot }
        elseif ($hiveName -eq 'HKU') { $hive = [Microsoft.Win32.Registry]::Users }
        if ($hive -and $sub) {
            $key = $hive.OpenSubKey($sub, $true)
            if ($key) {
                try { $key.DeleteValue('', $false) } catch { }
                $key.Close()
            }
        }
    } catch { }
}

function Invoke-UniInstallerKeys {
    param($ReExact)
    foreach ($root in @(
        'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall',
        'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall',
        'HKCU:\Software\Microsoft\Windows\CurrentVersion\Uninstall'
    )) {
        if (-not (Test-Path -LiteralPath $root)) { continue }
        foreach ($k in @(Get-ChildItem -LiteralPath $root -ErrorAction SilentlyContinue)) {
            $hit = $ReExact.IsMatch($k.PSChildName)
            if (-not $hit) {
                $props = Get-ItemProperty -LiteralPath $k.PSPath -ErrorAction SilentlyContinue
                foreach ($pn in @('DisplayName', 'Publisher', 'InstallLocation', 'DisplayIcon', 'UninstallString', 'DisplayVersion')) {
                    $v = $props.$pn
                    if ($v -and $ReExact.IsMatch([string]$v)) { $hit = $true; break }
                }
            }
            if ($hit) {
                Update-UniLine ("[{0}] uninstall: removing {1} ..." -f (Get-UniElapsed), $k.PSChildName)
                Remove-UniRegistryKey -ProviderPath $k.PSPath
                $script:UniStats.RegKeys++
                Clear-UniLine
                Write-Host ("  uninstall entry removed: {0}" -f $k.PSChildName) -ForegroundColor Green
            }
        }
    }
    foreach ($root in @(
        'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\App Paths',
        'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\App Paths'
    )) {
        if (-not (Test-Path -LiteralPath $root)) { continue }
        foreach ($k in @(Get-ChildItem -LiteralPath $root -ErrorAction SilentlyContinue)) {
            if ($ReExact.IsMatch($k.PSChildName)) {
                Update-UniLine ("[{0}] app paths: removing {1} ..." -f (Get-UniElapsed), $k.PSChildName)
                Remove-UniRegistryKey -ProviderPath $k.PSPath
                $script:UniStats.RegKeys++
                Clear-UniLine
                Write-Host ("  app path removed: {0}" -f $k.PSChildName) -ForegroundColor Green
            }
        }
    }
    foreach ($root in @(
        'HKCU:\Software\Microsoft\Windows\CurrentVersion\Run',
        'HKCU:\Software\Microsoft\Windows\CurrentVersion\RunOnce',
        'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Run',
        'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\RunOnce',
        'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Run',
        'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\RunOnce'
    )) {
        if (-not (Test-Path -LiteralPath $root)) { continue }
        $item = Get-Item -LiteralPath $root -ErrorAction SilentlyContinue
        if (-not $item) { continue }
        foreach ($vn in @($item.GetValueNames())) {
            $data = $item.GetValue($vn)
            if ($ReExact.IsMatch($vn) -or ($data -and $ReExact.IsMatch([string]$data))) {
                $vnShow = if ([string]::IsNullOrEmpty($vn)) { '(default)' } else { $vn }
                Remove-UniRegistryValue -ProviderPath $root -ValueName $vn
                $script:UniStats.RegValues++
                Clear-UniLine
                Write-Host ("  run entry removed: {0} :: {1}" -f $root, $vnShow) -ForegroundColor Green
            }
        }
    }
    Clear-UniLine
    Write-Host ("  uninstall / run keys: {0} keys, {1} values." -f $script:UniStats.RegKeys, $script:UniStats.RegValues) -ForegroundColor Green
}

# ---------------------------------------------------------------------------
# 6. deep registry sweep (Software hives + HKCR / COM / TypeLib)
# ---------------------------------------------------------------------------
function Invoke-UniRegistrySweep {
    param($ReExact, $ReLoose)
    $denyPrefixes = @('HKLM\SOFTWARE\Microsoft', 'HKLM\SOFTWARE\WOW6432Node\Microsoft', 'HKCU\Software\Microsoft')
    $task = $null
    Update-UniLine ("[{0}] initializing registry scanner ..." -f (Get-UniElapsed))
    Ensure-UniRegCollect
    if ($script:UniRegOk) {
        try {
            [UniRegCollectV3]::ResetCounters()
            $task = [UniRegCollectV3]::CollectAsync($ReExact.ToString(), $ReLoose.ToString(), $denyPrefixes)
        } catch { $task = $null }
    }
    if (-not $task) {
        Clear-UniLine
        Write-Host "  registry collector unavailable - skipping deep sweep." -ForegroundColor Yellow
        return
    }
    while (-not $task.IsCompleted) {
        $sc = 0; $mt = 0
        try { $sc = [UniRegCollectV3]::Scanned; $mt = [UniRegCollectV3]::Matched } catch { }
        Update-UniLine ("[{0}] registry sweep: keys {1:N0} scanned · {2} matched ..." -f (Get-UniElapsed), $sc, $mt)
        Start-Sleep -Milliseconds 100
    }
    $items = @()
    try { $items = @($task.Result) } catch { }
    if ($items.Count -eq 0) {
        Clear-UniLine
        Write-Host "  registry sweep: nothing matched." -ForegroundColor Green
        return
    }
    $script:UniRegSweepFound = $true
    $i = 0
    foreach ($item in $items) {
        $i++
        if ($item.StartsWith('K:')) {
            $rp = 'Registry::' + $item.Substring(2)
            Update-UniLine ("[{0}] registry sweep [{1}/{2}]: key {3}" -f (Get-UniElapsed), $i, $items.Count, $item.Substring(2))
            Remove-UniRegistryKey -ProviderPath $rp
            $script:UniStats.RegKeys++
            Clear-UniLine
            Write-Host ("  registry key removed: {0}" -f $item.Substring(2)) -ForegroundColor Green
        } else {
            $sep = $item.IndexOf([char]1)
            if ($sep -lt 0) { continue }
            $rp = 'Registry::' + $item.Substring(2, $sep - 2)
            $vn = $item.Substring($sep + 1)
            $vnShow = if ([string]::IsNullOrEmpty($vn)) { '(default)' } else { $vn }
            Update-UniLine ("[{0}] registry sweep [{1}/{2}]: value {3} :: {4}" -f (Get-UniElapsed), $i, $items.Count, $item.Substring(2, $sep - 2), $vnShow)
            Remove-UniRegistryValue -ProviderPath $rp -ValueName $vn
            $script:UniStats.RegValues++
            Clear-UniLine
            Write-Host ("  registry value removed: {0} :: {1}" -f $item.Substring(2, $sep - 2), $vnShow) -ForegroundColor DarkGreen
        }
    }
    Clear-UniLine
    Write-Host ("  registry sweep done: {0} keys, {1} values." -f $script:UniStats.RegKeys, $script:UniStats.RegValues) -ForegroundColor Green
}

# ---------------------------------------------------------------------------
# 7. environment variables + PATH
# ---------------------------------------------------------------------------
function Invoke-UniEnvVars {
    param($ReExact)
    foreach ($scope in @('User', 'Machine')) {
        $vars = $null
        try { $vars = [Environment]::GetEnvironmentVariables($scope) } catch { continue }
        if (-not $vars) { continue }
        foreach ($key in @($vars.Keys)) {
            $val = [string]$vars[$key]
            if ($ReExact.IsMatch($key) -or $ReExact.IsMatch($val)) {
                try {
                    [Environment]::SetEnvironmentVariable($key, $null, $scope)
                    $script:UniStats.EnvVars++
                    Clear-UniLine
                    Write-Host ("  env var removed ({0}): {1}" -f $scope, $key) -ForegroundColor Green
                } catch { }
            }
        }
        $path = [Environment]::GetEnvironmentVariable('Path', $scope)
        if ($path) {
            $oldParts = @($path -split ';')
            $newParts = @($oldParts | Where-Object { $_ -and -not $ReExact.IsMatch($_) })
            if ($newParts.Count -ne $oldParts.Count) {
                $joined = $newParts -join ';'
                try {
                    [Environment]::SetEnvironmentVariable('Path', $joined, $scope)
                    $script:UniStats.EnvVars++
                    if ($scope -eq 'User') { $env:Path = $joined }
                    Clear-UniLine
                    Write-Host ("  PATH cleaned ({0}): removed {1} entr(ies)." -f $scope, ($oldParts.Count - $newParts.Count)) -ForegroundColor Green
                } catch { }
            }
        }
    }
    Clear-UniLine
    Write-Host ("  environment: {0} variable(s) removed." -f $script:UniStats.EnvVars) -ForegroundColor Green
}

# ---------------------------------------------------------------------------
# 8. shortcuts / pins (Start Menu, Desktop, Taskbar, Recent)
# ---------------------------------------------------------------------------
function Invoke-UniShortcuts {
    param($ReLoose)
    $dirs = @()
    foreach ($d in @(
        (Join-Path $env:APPDATA 'Microsoft\Windows\Start Menu\Programs'),
        (Join-Path $env:ProgramData 'Microsoft\Windows\Start Menu\Programs'),
        (Join-Path $env:USERPROFILE 'Desktop'),
        (Join-Path $env:PUBLIC 'Desktop'),
        (Join-Path $env:APPDATA 'Microsoft\Internet Explorer\Quick Launch\User Pinned\TaskBar'),
        (Join-Path $env:APPDATA 'Microsoft\Internet Explorer\Quick Launch\User Pinned\StartMenu'),
        (Join-Path $env:APPDATA 'Microsoft\Windows\Recent')
    )) {
        if ($d -and (Test-Path -LiteralPath $d -PathType Container)) { $dirs += $d }
    }
    $shell = $null
    try { $shell = New-Object -ComObject WScript.Shell } catch { }
    foreach ($d in $dirs) {
        $files = @()
        try {
            $files = @(Get-ChildItem -LiteralPath $d -Recurse -File -ErrorAction SilentlyContinue | Where-Object { $_.Extension -match '^\.(lnk|url|appref-ms)$' })
        } catch { }
        foreach ($f in $files) {
            $hit = $ReLoose.IsMatch($f.Name)
            if (-not $hit -and $shell) {
                try {
                    $sc = $shell.CreateShortcut($f.FullName)
                    if ($sc.TargetPath -and $ReLoose.IsMatch([string]$sc.TargetPath)) { $hit = $true }
                } catch { }
            }
            if ($hit) {
                Update-UniLine ("[{0}] shortcuts: {1}" -f (Get-UniElapsed), $f.FullName)
                if (Remove-UniTarget -Path $f.FullName) {
                    $script:UniStats.Shortcuts++
                    Clear-UniLine
                    Write-Host ("  shortcut removed: {0}" -f $f.FullName) -ForegroundColor Green
                }
            }
        }
    }
    Clear-UniLine
    Write-Host ("  shortcuts: {0} removed." -f $script:UniStats.Shortcuts) -ForegroundColor Green
}

# ---------------------------------------------------------------------------
# 9. MRU / recent entries
# ---------------------------------------------------------------------------
function Invoke-UniMru {
    param($ReExact)
    foreach ($root in @(
        'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\RecentDocs',
        'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\ComDlg32\OpenSaveMRU',
        'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\ComDlg32\LastVisitedPidlMRU',
        'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\ComDlg32\OpenSavePidlMRU',
        'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\RunMRU',
        'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\TypedPaths',
        'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\WordWheelQuery'
    )) {
        if (-not (Test-Path -LiteralPath $root)) { continue }
        $key = Get-Item -LiteralPath $root -ErrorAction SilentlyContinue
        if (-not $key) { continue }
        foreach ($vn in @($key.GetValueNames())) {
            if ($vn -eq 'MRUListEx') { continue }
            $data = $key.GetValue($vn)
            $text = ''
            if ($data -is [byte[]]) { $text = [System.Text.Encoding]::Unicode.GetString($data) }
            elseif ($data) { $text = [string]$data }
            if ($text -and $ReExact.IsMatch($text)) {
                $vnShow = if ([string]::IsNullOrEmpty($vn)) { '(default)' } else { $vn }
                Remove-UniRegistryValue -ProviderPath $root -ValueName $vn
                $script:UniStats.RegValues++
                Clear-UniLine
                Write-Host ("  MRU entry removed: {0} :: {1}" -f $root, $vnShow) -ForegroundColor DarkGreen
            }
        }
    }
    Clear-UniLine
    Write-Host "  MRU / recent: done." -ForegroundColor Green
}

# ---------------------------------------------------------------------------
# 10. filesystem obliteration (parallel scan + live counters + per-item log)
# ---------------------------------------------------------------------------
function Invoke-UniFileSweep {
    param([string]$ExactPat, [string]$LoosePat, [string[]]$ExplicitPaths)

    # explicit paths first (instant satisfaction, token sweep covers the rest)
    foreach ($p in $ExplicitPaths) {
        Update-UniLine ("[{0}] explicit target: {1}" -f (Get-UniElapsed), $p)
        if (Remove-UniTarget -Path $p) {
            $script:UniStats.Files++
            Clear-UniLine
            Write-Host ("  deleted: {0}" -f $p) -ForegroundColor Green
        } else {
            [void]$script:UniFailed.Add($p)
            Clear-UniLine
            Write-Host ("  BLOCKED: {0}" -f $p) -ForegroundColor Red
        }
    }

    $sd = $env:SystemDrive
    $prog86 = $null
    try { $prog86 = ${env:ProgramFiles(x86)} } catch { }
    $rootDenyNames = @('Windows', 'Users', 'Program Files', 'Program Files (x86)', 'ProgramData', 'Temp', 'System Volume Information', 'Recovery', 'Windows.old', '$Recycle.Bin', 'Config.Msi', 'MSOCache', 'PerfLogs', '$WinREAgent', 'pagefile.sys', 'hiberfil.sys', 'swapfile.sys', 'DumpStack.log.tmp', 'bootmgr', 'BOOTSECT.BAK')
    
    # Discover package manager explicit paths for the target tokens
    $explicitPkgPaths = @()
    foreach ($tok in $pat.Tokens) {
        # Scoop
        if (Test-Path -LiteralPath (Join-Path $env:USERPROFILE 'scoop') -PathType Container) {
            $explicitPkgPaths += (Join-Path $env:USERPROFILE 'scoop')
        }
        if (Test-Path -LiteralPath (Join-Path $env:LOCALAPPDATA 'Scoop') -PathType Container) {
            $explicitPkgPaths += (Join-Path $env:LOCALAPPDATA 'Scoop')
        }
        # uv
        if (Test-Path -LiteralPath (Join-Path $env:APPDATA 'uv') -PathType Container) {
            $explicitPkgPaths += (Join-Path $env:APPDATA 'uv')
        }
        # Chocolatey
        if (Test-Path -LiteralPath 'C:\ProgramData\chocolatey' -PathType Container) {
            $explicitPkgPaths += 'C:\ProgramData\chocolatey'
        }
        # Winget (DesktopAppInstaller packages cache)
        if (Test-Path -LiteralPath (Join-Path $env:LOCALAPPDATA 'Packages') -PathType Container) {
            $explicitPkgPaths += (Join-Path $env:LOCALAPPDATA 'Packages')
        }
        # npm/pnpm/yarn global
        if (Test-Path -LiteralPath (Join-Path $env:APPDATA 'npm') -PathType Container) {
            $explicitPkgPaths += (Join-Path $env:APPDATA 'npm')
        }
        if (Test-Path -LiteralPath (Join-Path $env:LOCALAPPDATA 'pnpm') -PathType Container) {
            $explicitPkgPaths += (Join-Path $env:LOCALAPPDATA 'pnpm')
        }
        # pipx
        if (Test-Path -LiteralPath (Join-Path $env:APPDATA 'pipx') -PathType Container) {
            $explicitPkgPaths += (Join-Path $env:APPDATA 'pipx')
        }
        # Cargo/Rust
        if (Test-Path -LiteralPath (Join-Path $env:USERPROFILE '.cargo') -PathType Container) {
            $explicitPkgPaths += (Join-Path $env:USERPROFILE '.cargo')
        }
        # Go
        if (Test-Path -LiteralPath (Join-Path $env:USERPROFILE 'go') -PathType Container) {
            $explicitPkgPaths += (Join-Path $env:USERPROFILE 'go')
        }
        # Bun
        if (Test-Path -LiteralPath (Join-Path $env:APPDATA 'bun') -PathType Container) {
            $explicitPkgPaths += (Join-Path $env:APPDATA 'bun')
        }
        # Deno
        if (Test-Path -LiteralPath (Join-Path $env:APPDATA 'deno') -PathType Container) {
            $explicitPkgPaths += (Join-Path $env:APPDATA 'deno')
        }
    }
    $explicitPkgPaths = @($explicitPkgPaths | Select-Object -Unique | Where-Object { Test-Path -LiteralPath $_ -PathType Container })

    $script:UniRootSpecs = @(
        @{ Path = $sd; Mode = 'A'; RootDeny = $rootDenyNames },
        @{ Path = (Join-Path $sd 'Temp'); Mode = 'T'; RootDeny = @() },
        @{ Path = (Join-Path $sd 'Windows\Temp'); Mode = 'T'; RootDeny = @() },
        @{ Path = (Join-Path $sd 'Windows\Tasks'); Mode = 'T'; RootDeny = @() },
        @{ Path = (Join-Path $sd 'Windows\System32\Tasks'); Mode = 'T'; RootDeny = @() },
        @{ Path = (Join-Path $sd 'Windows\Prefetch'); Mode = 'T'; RootDeny = @() },
        @{ Path = $env:USERPROFILE; Mode = 'B'; RootDeny = @() },
        @{ Path = $env:ProgramData; Mode = 'A'; RootDeny = @() },
        @{ Path = $env:ProgramFiles; Mode = 'A'; RootDeny = @() },
        @{ Path = $prog86; Mode = 'A'; RootDeny = @() },
        @{ Path = (Join-Path $sd 'Users\Public'); Mode = 'B'; RootDeny = @() },
        # AppData\Local\Packages (Windows App Installer / Winget cache) - Nuclear mode for exact matches
        @{ Path = (Join-Path $env:LOCALAPPDATA 'Packages'); Mode = 'N'; RootDeny = @() },
        # AppData\Roaming (uv, pipx, npm, etc.) - Nuclear mode
        @{ Path = $env:APPDATA; Mode = 'N'; RootDeny = @() },
        # Scoop locations - Nuclear mode
        @{ Path = (Join-Path $env:USERPROFILE 'scoop'); Mode = 'N'; RootDeny = @() },
        @{ Path = (Join-Path $env:LOCALAPPDATA 'Scoop'); Mode = 'N'; RootDeny = @() }
    )
    # Add discovered package manager paths as Nuclear mode roots
    foreach ($p in $explicitPkgPaths) {
        $script:UniRootSpecs += @{ Path = $p; Mode = 'N'; RootDeny = @() }
    }
    $script:UniRootSpecs = @($script:UniRootSpecs | Where-Object {
        $_.Path -and $_.Path.StartsWith($sd, [System.StringComparison]::OrdinalIgnoreCase) -and (Test-Path -LiteralPath $_.Path -PathType Container)
    })
    $script:UniDenyPaths = @()
    if ($env:ProgramFiles) {
        $script:UniDenyPaths += (Join-Path $env:ProgramFiles 'WindowsApps')
        $script:UniDenyPaths += (Join-Path $env:ProgramFiles 'Microsoft Shared')
        $script:UniDenyPaths += (Join-Path $env:ProgramFiles 'Common Files\Microsoft Shared')
        $script:UniDenyPaths += (Join-Path $env:ProgramFiles 'Windows NT')
        $script:UniDenyPaths += (Join-Path $env:ProgramFiles 'Internet Explorer')
    }
    if ($prog86) {
        $denyPaths += (Join-Path $prog86 'Microsoft Shared')
        $denyPaths += (Join-Path $prog86 'Windows NT')
        $denyPaths += (Join-Path $prog86 'Internet Explorer')
    }
    if ($env:ProgramData) { $denyPaths += (Join-Path $env:ProgramData 'Package Cache') }
    $denyPaths = @($denyPaths | Where-Object { $_ -and (Test-Path -LiteralPath $_ -PathType Container) })

    $protected = @()
    if ($PSCommandPath) { $protected += [System.IO.Path]::GetFullPath($PSCommandPath) }
    $mod = Get-Module -Name 'CodexProfileFunctions' -ErrorAction SilentlyContinue | Select-Object -First 1
    if ($mod -and $mod.ModuleBase) {
        $protected += (Join-Path $mod.ModuleBase ($mod.Name + '.psm1'))
        $protected += (Join-Path $mod.ModuleBase ($mod.Name + '.psd1'))
    }
    $script:UniProtected = $protected

    # launch root scans in parallel waves (cap 3) so the big roots overlap
    # instead of adding up - combined live counters while they run
    Ensure-UniSweepCollect
    if (-not $script:UniCollectOk) {
        Clear-UniLine
        Write-Host "  filesystem collector unavailable - skipping sweep." -ForegroundColor Yellow
        return
    }
    [UniSweepCollectV3]::ResetCounters()
    $rootQueue = @($script:UniRootSpecs)
    $running = @()
    $completed = @()
    $maxConcurrent = 3
    while ($rootQueue.Count -gt 0 -or $running.Count -gt 0) {
        while ($rootQueue.Count -gt 0 -and $running.Count -lt $maxConcurrent) {
            $rs = $rootQueue[0]
            $rootQueue = @($rootQueue | Select-Object -Skip 1)
            try {
                $task = [UniSweepCollectV3]::CollectAsync($rs.Path, $rs.Mode, $ExactPat, $LoosePat, $script:UniDenyPaths, $script:UniProtected, @($rs.RootDeny))
                if ($task) { $running += @{ Path = $rs.Path; Mode = $rs.Mode; Task = $task } }
            } catch { }
        }
        if ($running.Count -eq 0) { break }
        $sc = 0; $mt = 0
        try { $sc = [UniSweepCollectV3]::Scanned; $mt = [UniSweepCollectV3]::Matched } catch { }
        Update-UniLine ("[{0}] scanning roots in parallel: entries {1:N0} · matched {2} · active {3} ..." -f (Get-UniElapsed), $sc, $mt, $running.Count)
        Start-Sleep -Milliseconds 100
        $still = @()
        foreach ($r in $running) {
            if ($r.Task.IsCompleted) { $completed += $r } else { $still += $r }
        }
        $running = $still
    }
    Clear-UniLine
    Write-Host ("  scanned {0} root(s): {1}" -f $completed.Count, (@($completed | ForEach-Object { $_.Path }) -join ', ')) -ForegroundColor Cyan
    foreach ($t in $completed) {
        $cands = @()
        try { $cands = @($t.Task.Result) } catch { }
        if ($cands.Count -eq 0) {
            Clear-UniLine
            Write-Host ("  nothing matched under {0}." -f $t.Path) -ForegroundColor DarkGray
            continue
        }
        $i = 0
        foreach ($c in $cands) {
            $i++
            $wasDir = $false
            try { $wasDir = [System.IO.Directory]::Exists($c) } catch { }
            Update-UniLine ("[{0}] deleting [{1}/{2}] {3} ..." -f (Get-UniElapsed), $i, $cands.Count, $c)
            if (Remove-UniTarget -Path $c) {
                if ($wasDir) { $script:UniStats.Dirs++ } else { $script:UniStats.Files++ }
                Clear-UniLine
                Write-Host ("  deleted: {0}" -f $c) -ForegroundColor Green
            } else {
                [void]$script:UniFailed.Add($c)
                Clear-UniLine
                Write-Host ("  BLOCKED: {0}" -f $c) -ForegroundColor Red
            }
        }
    }
    Clear-UniLine
    Write-Host ("  filesystem sweep done: {0} file(s), {1} dir(s) deleted." -f $script:UniStats.Files, $script:UniStats.Dirs) -ForegroundColor Green
}

# ---------------------------------------------------------------------------
# 11. final round: re-kill, release handles, retry blocked items + re-scan nuclear roots
# ---------------------------------------------------------------------------
function Invoke-UniFinal {
    param($ReExact, $ReLoose, $ExactPat, $LoosePat, $RootSpecs, $DenyPaths, $Protected)
    Invoke-UniKillProcesses -ReExact $ReExact
    
    # Re-scan nuclear mode roots (Mode N) AND user profile for any recreated items after process kill
    $nuclearRoots = @($RootSpecs | Where-Object { $_.Mode -eq 'N' } | ForEach-Object { $_.Path } | Where-Object { Test-Path -LiteralPath $_ -PathType Container })
    # Also re-scan USERPROFILE (Mode B) since it can contain app data folders like .ollama
    $userProfile = $env:USERPROFILE
    if ($userProfile -and (Test-Path -LiteralPath $userProfile -PathType Container)) {
        $nuclearRoots += $userProfile
    }
    if ($nuclearRoots.Count -gt 0) {
        Clear-UniLine
        Write-Host "  re-scanning nuclear roots for recreated items..." -ForegroundColor Cyan
        foreach ($root in $nuclearRoots) {
            Update-UniLine ("[{0}] re-scanning {1} ..." -f (Get-UniElapsed), $root)
            $task = $null
            Ensure-UniSweepCollect
            if ($script:UniCollectOk) {
                try {
                    [UniSweepCollectV3]::ResetCounters()
                    $task = [UniSweepCollectV3]::CollectAsync($root, 'N', $ExactPat, $LoosePat, $DenyPaths, $Protected, @())
                } catch { $task = $null }
            }
            if ($task) {
                while (-not $task.IsCompleted) {
                    $sc = 0; $mt = 0
                    try { $sc = [UniSweepCollectV3]::Scanned; $mt = [UniSweepCollectV3]::Matched } catch { }
                    Update-UniLine ("[{0}] re-scanning {1} ... entries {2:N0} · matched {3}" -f (Get-UniElapsed), $root, $sc, $mt)
                    Start-Sleep -Milliseconds 100
                }
                $cands = @()
                try { $cands = @($task.Result) } catch { }
                foreach ($c in $cands) {
                    $wasDir = $false
                    try { $wasDir = [System.IO.Directory]::Exists($c) } catch { }
                    Update-UniLine ("[{0}] deleting recreated: {1}" -f (Get-UniElapsed), $c)
                    if (Remove-UniTarget -Path $c -MaxRounds 3) {
                        if ($wasDir) { $script:UniStats.Dirs++ } else { $script:UniStats.Files++ }
                        Clear-UniLine
                        Write-Host ("  deleted (recreated): {0}" -f $c) -ForegroundColor Green
                    }
                }
            }
        }
    }

    # final registry re-sweep: only runs when the first sweep matched something
    # (so clean runs pay nothing). Catches values that failed to delete the first
    # time or were re-created by processes killed in this final round, e.g.
    # per-app audio PolicyConfig default-value references.
    if ($script:UniRegSweepFound -or $script:UniFailed.Count -gt 0) {
        Clear-UniLine
        Write-Host '  re-scanning registry for recreated values ...' -ForegroundColor Cyan
        $regTask = $null
        Ensure-UniRegCollect
        if ($script:UniRegOk) {
            try {
                [UniRegCollectV3]::ResetCounters()
                $regTask = [UniRegCollectV3]::CollectAsync($ReExact.ToString(), $ReLoose.ToString(), @('HKLM\SOFTWARE\Microsoft', 'HKLM\SOFTWARE\WOW6432Node\Microsoft', 'HKCU\Software\Microsoft'))
            } catch { $regTask = $null }
        }
        if ($regTask) {
            while (-not $regTask.IsCompleted) {
                $sc = 0; $mt = 0
                try { $sc = [UniRegCollectV3]::Scanned; $mt = [UniRegCollectV3]::Matched } catch { }
                Update-UniLine ("[{0}] registry re-sweep: keys {1:N0} scanned · {2} matched ..." -f (Get-UniElapsed), $sc, $mt)
                Start-Sleep -Milliseconds 100
            }
            $ritems = @()
            try { $ritems = @($regTask.Result) } catch { }
            foreach ($item in $ritems) {
                if ($item.StartsWith('K:')) {
                    $rp = 'Registry::' + $item.Substring(2)
                    Update-UniLine ("[{0}] registry re-sweep: key {1}" -f (Get-UniElapsed), $item.Substring(2))
                    Remove-UniRegistryKey -ProviderPath $rp
                    $script:UniStats.RegKeys++
                    Clear-UniLine
                    Write-Host ("  registry key removed (final): {0}" -f $item.Substring(2)) -ForegroundColor Green
                } else {
                    $sep = $item.IndexOf([char]1)
                    if ($sep -lt 0) { continue }
                    $rp = 'Registry::' + $item.Substring(2, $sep - 2)
                    $vn = $item.Substring($sep + 1)
                    $vnShow = if ([string]::IsNullOrEmpty($vn)) { '(default)' } else { $vn }
                    Update-UniLine ("[{0}] registry re-sweep: value {1} :: {2}" -f (Get-UniElapsed), $item.Substring(2, $sep - 2), $vnShow)
                    Remove-UniRegistryValue -ProviderPath $rp -ValueName $vn
                    $script:UniStats.RegValues++
                    Clear-UniLine
                    Write-Host ("  registry value removed (final): {0} :: {1}" -f $item.Substring(2, $sep - 2), $vnShow) -ForegroundColor DarkGreen
                }
            }
            Clear-UniLine
            Write-Host ("  registry re-sweep done: {0} leftover(s) found and removed." -f $ritems.Count) -ForegroundColor Green
        }
    }

    if ($script:UniFailed.Count -eq 0) { return }
    $retry = @($script:UniFailed)
    $script:UniFailed = New-Object System.Collections.Generic.List[string]
    $needExplorer = $false
    foreach ($p in $retry) {
        if (-not (Test-Path -LiteralPath $p)) { continue }
        foreach ($l in @(Get-UniLockerPids -Path $p)) {
            try {
                $proc = Get-Process -Id $l -ErrorAction Stop
                if ($proc.ProcessName -eq 'explorer') { $needExplorer = $true }
            } catch { }
        }
    }
    if ($needExplorer) {
        Clear-UniLine
        Write-Host "  restarting Explorer once to release shell-extension handles ..." -ForegroundColor Cyan
        Stop-Process -Name explorer -Force -ErrorAction SilentlyContinue
        Start-Sleep -Milliseconds 1500
        Start-Process explorer.exe
        Start-Sleep -Milliseconds 1000
    }
    foreach ($p in $retry) {
        if (-not (Test-Path -LiteralPath $p)) { continue }
        Update-UniLine ("[{0}] final retry: {1}" -f (Get-UniElapsed), $p)
        if (Remove-UniTarget -Path $p -MaxRounds 5) {
            $script:UniStats.Files++
            Clear-UniLine
            Write-Host ("  deleted (final round): {0}" -f $p) -ForegroundColor Green
        } else {
            Clear-UniLine
            Write-Host ("  STILL BLOCKED: {0}" -f $p) -ForegroundColor Red
            [void]$script:UniFailed.Add($p)
        }
    }
}

# ---------------------------------------------------------------------------
# summary
# ---------------------------------------------------------------------------
function Write-UniSummary {
    $secs = [int](([DateTime]::UtcNow) - $script:UniStart).TotalSeconds
    $m = [math]::Floor($secs / 60); $s = $secs % 60
    Clear-UniLine
    Write-Host ''
    Write-Host ('  NUCLEAR OBLITERATION COMPLETE ({0}m {1}s)' -f $m, $s) -ForegroundColor Green
    Write-Host ('  ' + ('=' * 46))
    Write-Host ('  Processes Killed:      {0}' -f $script:UniStats.Processes)
    Write-Host ('  Services Deleted:      {0}' -f $script:UniStats.Services)
    Write-Host ('  Tasks Deleted:         {0}' -f $script:UniStats.Tasks)
    Write-Host ('  Firewall Rules:        {0}' -f $script:UniStats.Firewall)
    Write-Host ('  Registry Keys:         {0}' -f $script:UniStats.RegKeys)
    Write-Host ('  Registry Values:       {0}' -f $script:UniStats.RegValues)
    Write-Host ('  Env Vars Removed:      {0}' -f $script:UniStats.EnvVars)
    Write-Host ('  Shortcuts Removed:     {0}' -f $script:UniStats.Shortcuts)
    Write-Host ('  Files Deleted:         {0}' -f $script:UniStats.Files)
    Write-Host ('  Dirs Deleted:          {0}' -f $script:UniStats.Dirs)
    if ($script:UniFailed.Count -gt 0) {
        Write-Host ('  FAILED (blocked):     {0}' -f $script:UniFailed.Count) -ForegroundColor Red
        foreach ($f in @($script:UniFailed | Select-Object -Unique)) {
            Write-Host ("    blocked: {0}" -f $f) -ForegroundColor Red
        }
    } else {
        Write-Host '  FAILED (blocked):     0' -ForegroundColor Green
    }
    Write-Host ''
    Write-Host '  No reboot required. Zero leftovers. Back to shell.' -ForegroundColor Green
}

# ---------------------------------------------------------------------------
# the nuclear entry point
# ---------------------------------------------------------------------------
function uni {
    $raw = @($args)
    $names = New-Object System.Collections.Generic.List[string]
    $paths = New-Object System.Collections.Generic.List[string]
    $sweepOnly = $false
    foreach ($a in $raw) {
        $s = [string]$a
        if ($s -eq '--uni-sweep-only') { $sweepOnly = $true; continue }
        elseif ($s -match '^(/|--|-)[A-Za-z]') { continue }
        elseif ($s -match '^[A-Za-z]:[\\/]' -or $s -match '^\\\\' -or (Test-Path -LiteralPath $s -ErrorAction SilentlyContinue)) {
            try { $paths.Add([System.IO.Path]::GetFullPath($s)) } catch { $paths.Add($s) }
        }
        else { $names.Add($s) }
    }
    if ($names.Count -eq 0 -and $paths.Count -eq 0) {
        Write-Host 'uni: no target app names or paths given.' -ForegroundColor Yellow
        return
    }
    # derive extra tokens from explicit paths so the sweep covers their parents too
    foreach ($p in @($paths)) {
        foreach ($seg in @($p -split '[\\/]' | Where-Object { $_ })) {
            foreach ($part in @($seg -split '[^A-Za-z0-9]' | Where-Object { $_.Length -ge 3 })) {
                if (-not $names.Contains($part)) { $names.Add($part) }
            }
        }
    }
    $pat = Get-UniPatterns -Names @($names)
    if (-not $pat) {
        Write-Host ("uni: names too short or too generic to sweep safely: {0}" -f (@($names) -join ', ')) -ForegroundColor Yellow
        return
    }
    $ReExact = New-Object System.Text.RegularExpressions.Regex($pat.Exact, [System.Text.RegularExpressions.RegexOptions]::IgnoreCase)
    $ReLoose = New-Object System.Text.RegularExpressions.Regex($pat.Loose, [System.Text.RegularExpressions.RegexOptions]::IgnoreCase)

    Write-Host ('  SEARCH TERMS: {0}' -f ($pat.Tokens -join ', ')) -ForegroundColor Cyan
    Write-Host '  No countdown, no prompts, no reboot. Going now.' -ForegroundColor DarkGray
    $script:UniStart = [DateTime]::UtcNow

    Write-UniPhase 'Terminating related processes'
    Invoke-UniKillProcesses -ReExact $ReExact
    Write-UniPhase 'Obliterating services'
    Invoke-UniServices -ReExact $ReExact
    Write-UniPhase 'Deleting scheduled tasks'
    Invoke-UniTasks -ReExact $ReExact
    Write-UniPhase 'Removing firewall rules'
    Invoke-UniFirewall -ReExact $ReExact
    Write-UniPhase 'Uninstall / App Paths / Run keys'
    Invoke-UniInstallerKeys -ReExact $ReExact
    Write-UniPhase 'Deep registry & COM sweep'
    Invoke-UniRegistrySweep -ReExact $ReExact -ReLoose $ReLoose
    Write-UniPhase 'Cleaning environment variables'
    Invoke-UniEnvVars -ReExact $ReExact
    Write-UniPhase 'Removing shortcuts and pins'
    Invoke-UniShortcuts -ReLoose $ReLoose
    Write-UniPhase 'Cleaning MRU and recent lists'
    Invoke-UniMru -ReExact $ReExact
    Write-UniPhase 'Filesystem obliteration'
    Invoke-UniFileSweep -ExactPat $pat.Exact -LoosePat $pat.Loose -ExplicitPaths @($paths)
    Write-UniPhase 'Final cleanup round'
    Invoke-UniFinal -ReExact $ReExact -ReLoose $ReLoose -ExactPat $pat.Exact -LoosePat $pat.Loose -RootSpecs $script:UniRootSpecs -DenyPaths $script:UniDenyPaths -Protected $script:UniProtected

    if (-not $script:UniIsElevated -and $PSCommandPath -and $script:UniFailed.Count -gt 0) {
        $needElev = $false
        $pf86 = $null
        try { $pf86 = ${env:ProgramFiles(x86)} } catch { }
        foreach ($f in $script:UniFailed) {
            foreach ($base in @($env:ProgramFiles, $pf86, $env:ProgramData, (Join-Path $env:SystemDrive 'Windows\Temp'))) {
                if ($base -and $f.StartsWith($base, [System.StringComparison]::OrdinalIgnoreCase)) { $needElev = $true; break }
            }
            if (-not $needElev -and $f.StartsWith($env:SystemDrive + '\', [System.StringComparison]::OrdinalIgnoreCase) -and -not $f.StartsWith($env:SystemDrive + '\Users', [System.StringComparison]::OrdinalIgnoreCase)) { $needElev = $true }
            if ($needElev) { break }
        }
        if ($needElev) {
            Clear-UniLine
            Write-Host '  some leftovers need administrator rights - re-running elevated.' -ForegroundColor Cyan
            $inner = @('-NoProfile', '-ExecutionPolicy', 'Bypass', '-File', ('"' + $PSCommandPath + '"'), '--uni-sweep-only')
            foreach ($n in @($names)) { $inner += ('"' + $n + '"') }
            try { Start-Process -FilePath "$env:SystemRoot\System32\WindowsPowerShell\v1.0\powershell.exe" -ArgumentList $inner -Verb RunAs -Wait } catch { }
        }
    }

    Write-UniSummary
}

if ($MyInvocation.InvocationName -ne '.') {
    & 'uni' @args
}
